<?php /* TerraMoss admin panel - PHP/MySQL version */ ?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><meta name="robots" content="noindex,nofollow"><title>Terra Moss — Admin</title><link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;600&family=DM+Sans:wght@300;400;500&display=swap" rel="stylesheet"><style>
:root{--gd:#1a3a2a;--gm:#2d5a3d;--gl:#4a8c5c;--gp:#a8d5b5;--gmist:#e8f5ec;--earth:#8b6914;--cream:#faf8f3;--tx:#1c2b22;--txm:#5a7060;--w:#fff;--br:rgba(45,90,61,.15)}*{box-sizing:border-box;margin:0;padding:0}body{font-family:'DM Sans',sans-serif;background:#f4f6f4;color:var(--tx)}.login{min-height:100vh;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,var(--gd),#0d2218)}.login-box{background:#fff;padding:2.5rem;border-radius:20px;width:min(390px,94vw);text-align:center}.login-box h1,.top h2{font-family:'Playfair Display',serif;color:var(--gd)}input,textarea,select{width:100%;padding:10px 12px;border:1px solid var(--br);border-radius:8px;font-family:inherit;background:var(--cream)}textarea{min-height:75px}.btn{background:var(--gm);color:#fff;border:0;border-radius:22px;padding:9px 16px;cursor:pointer;font-family:inherit}.btn:hover{background:var(--gd)}.btn.sec{background:var(--gmist);color:var(--gd);border:1px solid var(--br)}.btn.danger{background:#e74c3c}.panel{display:none;min-height:100vh}.panel.active{display:flex}.side{width:245px;background:#0d1f16;color:var(--gp);padding:1.2rem;display:flex;flex-direction:column;gap:.5rem}.brand{font-family:'Playfair Display',serif;font-size:1.2rem;margin-bottom:1rem}.nav button,.store-link{width:100%;display:block;text-align:left;background:none;color:rgba(168,213,181,.7);border:0;border-radius:10px;padding:10px;cursor:pointer;text-decoration:none;font-family:inherit}.nav button.active,.nav button:hover,.store-link:hover{background:rgba(168,213,181,.12);color:var(--gp)}.main{flex:1;display:flex;flex-direction:column}.top{background:#fff;padding:1rem 1.5rem;border-bottom:1px solid var(--br);display:flex;justify-content:space-between}.content{padding:1.5rem;overflow:auto}.tab{display:none}.tab.active{display:block}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:1rem;margin-bottom:1.5rem}.card{background:#fff;border:1px solid var(--br);border-radius:12px;padding:1.2rem}.num{font-family:'Playfair Display',serif;font-size:2rem;color:var(--gd)}.wrap{background:#fff;border:1px solid var(--br);border-radius:12px;overflow:hidden;margin-bottom:1rem}.head{padding:1rem;border-bottom:1px solid var(--br);display:flex;justify-content:space-between;align-items:center;gap:.5rem;flex-wrap:wrap}table{width:100%;border-collapse:collapse}th,td{padding:.75rem;border-bottom:1px solid var(--br);font-size:.86rem;text-align:left}th{font-size:.74rem;text-transform:uppercase;color:var(--txm);background:#f9fafb}.row{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.fg{margin-bottom:1rem}.fg label{display:block;font-size:.82rem;color:var(--txm);margin-bottom:5px}.modal-ov{position:fixed;inset:0;background:rgba(0,0,0,.6);display:none;align-items:center;justify-content:center;z-index:50;padding:1rem}.modal-ov.open{display:flex}.modal{background:#fff;border-radius:16px;width:min(700px,96vw);max-height:92vh;overflow:auto;padding:1.5rem}.previews{display:flex;flex-wrap:wrap;gap:.5rem}.prev{width:80px;height:80px;position:relative;border-radius:8px;overflow:hidden;background:var(--gmist);border:1px solid var(--br)}.prev img{width:100%;height:100%;object-fit:cover}.prev button{position:absolute;right:2px;top:2px}.toast{position:fixed;bottom:2rem;left:50%;transform:translateX(-50%) translateY(100px);background:var(--gd);color:#fff;padding:12px 22px;border-radius:30px;z-index:99;transition:.3s}.toast.show{transform:translateX(-50%) translateY(0)}.badge{padding:3px 9px;border-radius:12px;font-size:.75rem}.pending{background:#fff3cd;color:#856404}.delivered{background:#d4edda;color:#155724}.cancelled{background:#f8d7da;color:#721c24}.confirmed{background:#d1ecf1;color:#0c5460}@media(max-width:800px){.side{width:65px}.side span{display:none}.cards,.row{grid-template-columns:1fr}.content{padding:1rem}table{min-width:850px}.wrap{overflow:auto}}
</style></head><body><div class="toast" id="toast"></div><div class="login" id="login"><div class="login-box"><div style="font-size:2.5rem">🌿</div><h1>Terra Moss Admin</h1><p style="color:var(--txm);margin:1rem 0">Login to manage products and orders</p><input type="password" id="pass" placeholder="Admin password" onkeydown="if(event.key==='Enter')login()"><br><br><button class="btn" style="width:100%" onclick="login()">Login →</button><p id="loginErr" style="color:#e74c3c;margin-top:1rem"></p></div></div>
<div class="panel" id="panel"><aside class="side"><div class="brand">Terra <span>Moss</span></div><div class="nav"><button class="active" onclick="tab('dashboard',this)">📊 <span>Dashboard</span></button><button onclick="tab('products',this)">📦 <span>Products</span></button><button onclick="tab('orders',this)">🛒 <span>Orders</span></button><button onclick="tab('revenue',this)">💰 <span>Revenue</span></button><button onclick="tab('content',this)">✏️ <span>Content</span></button></div><div style="margin-top:auto"><a class="store-link" href="index.php">← <span>Back to Store</span></a><button class="btn danger" style="width:100%;margin-top:.7rem" onclick="logout()">Logout</button></div></aside><main class="main"><div class="top"><h2 id="title">Dashboard</h2><span id="date"></span></div><div class="content">
<section id="tab-dashboard" class="tab active"><div class="cards"><div class="card"><div>Total Products</div><div class="num" id="sProducts">0</div></div><div class="card"><div>Total Orders</div><div class="num" id="sOrders">0</div></div><div class="card"><div>Pending</div><div class="num" id="sPending">0</div></div><div class="card"><div>Revenue</div><div class="num" id="sRevenue">৳0</div></div></div><div class="wrap"><div class="head"><h3>Recent Orders</h3></div><div id="recent"></div></div></section>
<section id="tab-products" class="tab"><div class="head"><select id="filterCat" style="max-width:220px" onchange="renderProducts()"><option value="all">All Categories</option><option value="plants">Plants</option><option value="terrariums">Terrariums</option><option value="paludariums">Paludariums</option><option value="other">Other</option></select><button class="btn" onclick="openProduct()">+ Add Product</button></div><div class="wrap"><table><thead><tr><th>Image</th><th>Name</th><th>Category</th><th>Cost</th><th>Price</th><th>Policy</th><th>Actions</th></tr></thead><tbody id="prodRows"></tbody></table></div></section>
<section id="tab-orders" class="tab"><div class="head"><select id="filterStatus" style="max-width:220px" onchange="renderOrders()"><option value="all">All Status</option><option>Pending</option><option>Confirmed</option><option>Delivered</option><option>Cancelled</option></select><button class="btn sec" onclick="loadOrders()">Refresh Orders</button></div><div class="wrap"><table><thead><tr><th>Order ID</th><th>Customer</th><th>Phone</th><th>Address</th><th>Delivery</th><th>Total</th><th>Payment</th><th>Bkash</th><th>Date</th><th>Status</th><th>Update</th></tr></thead><tbody id="orderRows"></tbody></table></div></section>
<section id="tab-revenue" class="tab"><div class="cards"><div class="card"><div>Delivered Revenue</div><div class="num" id="rRev">৳0</div></div><div class="card"><div>Cost</div><div class="num" id="rCost">৳0</div></div><div class="card"><div>Profit</div><div class="num" id="rProfit">৳0</div></div><div class="card"><div>Margin</div><div class="num" id="rMargin">0%</div></div></div><div class="wrap"><div class="head"><h3>Delivered Orders</h3></div><table><thead><tr><th>Order</th><th>Customer</th><th>Revenue</th><th>Cost</th><th>Profit</th></tr></thead><tbody id="revRows"></tbody></table></div></section>
<section id="tab-content" class="tab"><div class="wrap"><div class="head"><h3>Website Content</h3><button class="btn" onclick="saveContent()">Save Content</button></div><div style="padding:1rem"><div class="fg"><label>Hero Title</label><input id="heroTitle"></div><div class="fg"><label>Hero Subtitle</label><textarea id="heroSub"></textarea></div><div class="fg"><label>About Paragraph 1</label><textarea id="about1"></textarea></div><div class="fg"><label>About Paragraph 2</label><textarea id="about2"></textarea></div><div class="row"><div class="fg"><label>Phone</label><input id="phone"></div><div class="fg"><label>Email</label><input id="email"></div></div><div class="row"><div class="fg"><label>Address</label><input id="address"></div><div class="fg"><label>Bkash Number</label><input id="bkash"></div></div></div></div></section>
</div></main></div>
<div class="modal-ov" id="productModal"><div class="modal"><h2 id="modalTitle">Product</h2><input type="hidden" id="pId"><div class="row"><div class="fg"><label>Name *</label><input id="pName"></div><div class="fg"><label>Category *</label><select id="pCat"><option value="plants">Plants</option><option value="terrariums">Terrariums</option><option value="paludariums">Paludariums</option><option value="other">Other</option></select></div></div><div class="row"><div class="fg"><label>Cost Price</label><input type="number" id="pCost"></div><div class="fg"><label>Selling Price *</label><input type="number" id="pPrice"></div></div><div class="row"><div class="fg"><label>Badge</label><input id="pBadge"></div><div class="fg"><label>Emoji</label><input id="pEmoji" value="🌿"></div></div><div class="fg"><label>Short Description *</label><textarea id="pDesc"></textarea></div><div class="fg"><label>Full Description</label><textarea id="pFull"></textarea></div><div class="fg"><label>Features (one per line)</label><textarea id="pFeatures"></textarea></div><div class="fg"><label>Payment Policy</label><select id="pPolicy"><option value="cod">Cash on Delivery</option><option value="fifty">50% Bkash Advance Required</option></select></div><div class="fg"><label>Upload Product Image</label><input type="file" id="imgInput" accept="image/*" onchange="uploadImage()"><div id="uploadStatus" style="font-size:.82rem;color:var(--txm);margin-top:6px"></div></div><div class="fg"><label>Or paste Image URL</label><div style="display:flex;gap:.5rem"><input id="imgUrl"><button class="btn sec" onclick="addImageUrl()">Add</button></div></div><div class="previews" id="imgPreviews"></div><br><div style="display:flex;justify-content:flex-end;gap:.7rem"><button class="btn sec" onclick="closeProduct()">Cancel</button><button class="btn" onclick="saveProduct()">Save Product</button></div></div></div>
<script>
let products={plants:[],terrariums:[],paludariums:[],other:[]},orders=[],editImages=[],uploadingImage=false;const $=id=>document.getElementById(id);function toast(m){$('toast').textContent=m;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2600)}async function api(action,data=null){let opt=data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{};let r=await fetch('api.php?action='+action,opt);return r.json()}function allP(){return [...products.plants,...products.terrariums,...products.paludariums,...products.other]}function findP(id){return allP().find(p=>p.id===id)}function money(n){return '৳'+Number(n||0).toLocaleString()}
async function login(){let r=await api('login',{password:$('pass').value});if(r.ok){$('login').style.display='none';$('panel').classList.add('active');init()}else $('loginErr').textContent=r.error||'Login failed'}async function logout(){await api('logout');location.reload()}async function check(){let r=await api('session');if(r.admin){$('login').style.display='none';$('panel').classList.add('active');init()}}function tab(name,btn){document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));$('tab-'+name).classList.add('active');btn.classList.add('active');$('title').textContent={dashboard:'Dashboard',products:'Products',orders:'Orders',revenue:'Revenue',content:'Content'}[name];if(name==='orders')loadOrders();if(name==='revenue')renderRevenue();}
async function init(){$('date').textContent=new Date().toLocaleDateString();await loadProducts();await loadOrders();await loadContent();renderDashboard();renderProducts();renderOrders();renderRevenue()}async function loadProducts(){let r=await api('products');if(r.ok)products=r.products}async function loadOrders(){let r=await api('orders');if(r.ok){orders=r.orders;renderOrders();renderDashboard();renderRevenue()}}
function renderDashboard(){let st={p:allP().length,o:orders.length,pending:orders.filter(o=>o.status==='Pending').length,rev:orders.filter(o=>o.status==='Delivered').reduce((a,o)=>a+Number(o.total),0)};$('sProducts').textContent=st.p;$('sOrders').textContent=st.o;$('sPending').textContent=st.pending;$('sRevenue').textContent=money(st.rev);$('recent').innerHTML=orders.slice(0,5).length?`<table><tbody>${orders.slice(0,5).map(o=>`<tr><td>${o.id}</td><td>${o.name}</td><td>${money(o.total)}</td><td>${o.status}</td></tr>`).join('')}</tbody></table>`:'<p style="padding:1rem">No orders yet.</p>'}
function renderProducts(){let cat=$('filterCat').value,list=cat==='all'?allP():products[cat]||[];$('prodRows').innerHTML=list.map(p=>`<tr><td>${p.images&&p.images[0]?`<img src="${p.images[0]}" style="width:45px;height:45px;object-fit:cover;border-radius:6px">`:(p.emoji||'🌿')}</td><td>${p.name}</td><td>${p.category}</td><td>${money(p.costPrice)}</td><td>${money(p.price)}</td><td>${p.paymentPolicy==='fifty'?'50% Advance':'COD'}</td><td><button class="btn sec" onclick="openProduct('${p.id}')">Edit</button> <button class="btn danger" onclick="deleteProduct('${p.id}')">Delete</button></td></tr>`).join('')||'<tr><td colspan="7">No products.</td></tr>'}
function renderOrders(){let f=$('filterStatus').value,list=f==='all'?orders:orders.filter(o=>o.status===f);$('orderRows').innerHTML=list.map(o=>`<tr><td>${o.id}</td><td>${o.name}</td><td>${o.phone}</td><td>${o.address}</td><td>${(o.deliveryArea==='outside_dhaka'?'Outside Dhaka':'Inside Dhaka')}<br>${money(o.deliveryCharge||0)}</td><td>${money(o.total)}</td><td>${o.payLabel||o.payment}</td><td>${o.bkashFrom?o.bkashFrom+' / ':''}${o.bkashTrx||'—'}</td><td>${o.date}</td><td><span class="badge ${String(o.status).toLowerCase()}">${o.status}</span></td><td><select onchange="updateStatus('${o.id}',this.value)">${['Pending','Confirmed','Delivered','Cancelled'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')||'<tr><td colspan="11">No orders.</td></tr>'}
async function updateStatus(id,status){let r=await api('update_order_status',{id,status});if(r.ok){toast('Order updated');await loadOrders()}else toast(r.error||'Failed')}
function renderRevenue(){let delivered=orders.filter(o=>o.status==='Delivered'),rev=0,cost=0;delivered.forEach(o=>{rev+=Number(o.total);(o.items||[]).forEach(i=>cost+=Number(i.costPrice||0)*Number(i.qty||0))});let profit=rev-cost;$('rRev').textContent=money(rev);$('rCost').textContent=money(cost);$('rProfit').textContent=money(profit);$('rMargin').textContent=rev?Math.round(profit/rev*100)+'%':'0%';$('revRows').innerHTML=delivered.map(o=>{let c=(o.items||[]).reduce((a,i)=>a+Number(i.costPrice||0)*Number(i.qty||0),0);return `<tr><td>${o.id}</td><td>${o.name}</td><td>${money(o.total)}</td><td>${money(c)}</td><td>${money(o.total-c)}</td></tr>`}).join('')||'<tr><td colspan="5">No delivered orders.</td></tr>'}
function openProduct(id=''){editImages=[];uploadingImage=false;if($('imgInput'))$('imgInput').value='';if($('uploadStatus'))$('uploadStatus').textContent='';$('pId').value=id;$('modalTitle').textContent=id?'Edit Product':'Add Product';let p=id?findP(id):null;$('pName').value=p?.name||'';$('pCat').value=p?.category||'plants';$('pCost').value=p?.costPrice||'';$('pPrice').value=p?.price||'';$('pBadge').value=p?.badge||'';$('pEmoji').value=p?.emoji||'🌿';$('pDesc').value=p?.desc||'';$('pFull').value=p?.fullDesc||'';$('pFeatures').value=(p?.features||[]).join('\n');$('pPolicy').value=p?.paymentPolicy||'cod';editImages=[...(p?.images||[])];renderImages();$('productModal').classList.add('open')}function closeProduct(){$('productModal').classList.remove('open')}function renderImages(){$('imgPreviews').innerHTML=editImages.map((u,i)=>`<div class="prev"><img src="${u}"><button onclick="editImages.splice(${i},1);renderImages()">×</button></div>`).join('')}function addImageUrl(){let u=$('imgUrl').value.trim();if(u){editImages.push(u);$('imgUrl').value='';renderImages()}}
function uploadStatus(msg,isError=false){let el=$('uploadStatus');if(el){el.textContent=msg||'';el.style.color=isError?'#e74c3c':'var(--txm)'}}
async function uploadImage(){let input=$('imgInput'),f=input?.files?.[0];if(!f)return true;if(uploadingImage){toast('Image is still uploading. Please wait.');return false}uploadingImage=true;uploadStatus('Uploading image, please wait...');try{let fd=new FormData();fd.append('image',f);let r=await fetch('api.php?action=upload_image',{method:'POST',body:fd});let txt=await r.text();let j;try{j=JSON.parse(txt)}catch(e){throw new Error('Server did not return JSON. Check error_log. Response: '+txt.slice(0,120))}if(!r.ok||!j.ok)throw new Error(j.error||'Upload failed');editImages.push(j.url);renderImages();toast('Image uploaded');uploadStatus('Image uploaded successfully. Now save the product.');input.value='';return true}catch(e){uploadStatus(e.message||'Upload failed',true);toast('Image upload failed');return false}finally{uploadingImage=false}}
async function saveProduct(){if(uploadingImage)return toast('Please wait for image upload to finish');if($('imgInput')?.files?.length){let ok=await uploadImage();if(!ok)return}let data={id:$('pId').value,name:$('pName').value.trim(),category:$('pCat').value,price:Number($('pPrice').value),costPrice:Number($('pCost').value||0),badge:$('pBadge').value,emoji:$('pEmoji').value||'🌿',desc:$('pDesc').value,fullDesc:$('pFull').value,features:$('pFeatures').value.split('\n').map(x=>x.trim()).filter(Boolean),paymentPolicy:$('pPolicy').value,images:editImages};if(!data.name||!data.price||!data.desc)return toast('Fill required fields');let r=await api('save_product',data);if(r.ok){toast('Product saved');closeProduct();await loadProducts();renderProducts();renderDashboard()}else toast(r.error||'Save failed')}
async function deleteProduct(id){if(!confirm('Delete this product?'))return;let r=await api('delete_product',{id});if(r.ok){toast('Deleted');await loadProducts();renderProducts();renderDashboard()}else toast(r.error||'Delete failed')}
async function loadContent(){let r=await api('content');let c=r.content||{};$('heroTitle').value=c.heroTitle||'Bring Nature Indoors with Us';$('heroSub').value=c.heroSub||'Handcrafted terrariums, paludariums, and rare tropical plants — curated for enthusiasts who believe living art belongs in every space.';$('about1').value=c.about1||'TerraMoss was born from a deep love for miniature ecosystems.';$('about2').value=c.about2||'Based in Bangladesh, we craft and curate terrariums, paludariums, and rare tropical plants.';$('phone').value=c.phone||'+880 1XXXXXXXXX';$('email').value=c.email||'hello@terraverde.com.bd';$('address').value=c.address||'Dhaka, Bangladesh';$('bkash').value=c.bkash||'01XXXXXXXXX'}async function saveContent(){let content={heroTitle:$('heroTitle').value,heroSub:$('heroSub').value,about1:$('about1').value,about2:$('about2').value,phone:$('phone').value,email:$('email').value,address:$('address').value,bkash:$('bkash').value};let r=await api('save_content',{content});toast(r.ok?'Content saved':r.error||'Save failed')}
check();
</script></body></html>
